import re

from moler.cmd.commandtextualgeneric import CommandTextualGeneric
from moler.exceptions import CommandFailure
from moler.exceptions import ParsingDone


class VrhaMem(CommandTextualGeneric):
    """VrhaMem command class."""

    def __init__(self, connection, port, device, address, options=None, value=None, prompt=None, newline_chars=None, runner=None):
        """
        Check the antenna in the register.

        :param connection: moler connection to device, terminal when command is executed.
        :param port: port where antenna is connected.
        :param device: antenna number.
        :param address: antenna address.
        :param options: command options.
        :param value: value to change in the register.
        :param prompt: expected prompt sending by device after command execution.
        :param newline_chars: characters to split lines.
        :param runner: runner to run command.
        """
        super(VrhaMem, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.port = port
        self.device = device
        self.address = address
        self.options = options
        self.value = value
        self.current_ret["RESULT"] = None

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        cmd_params = f"{self.port} {self.device} {self.address}"

        if self.options:
            cmd_params = f"{self.options} {cmd_params}"
        if self.value:
            cmd_params = f"{cmd_params} {self.value}"
        return f"vrha-mem {cmd_params}"

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_file_error(line)
                self._parse_command_error(line)
                self._parse_connection_error(line)
                self._parse_address_error(line)
                self._parse_line(line)
            except ParsingDone:
                pass
        return super(VrhaMem, self).on_new_line(line, is_full_line)

    # Unable to open '/dev/vrha1.2': No such file or directory
    _re_no_such_file = re.compile(r'(?P<FILE>.*No\s+such\s+file\s+or\s+directory)', re.I)

    def _parse_file_error(self, line):
        if self._regex_helper.search_compiled(VrhaMem._re_no_such_file, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group("FILE")))
            raise ParsingDone

    # /usr/bin/vrha-mem: illegal option -- -
    _re_usage = re.compile(r'(?P<USAGE>.*illegal\s+option.+)', re.I)

    def _parse_command_error(self, line):
        if self._regex_helper.search_compiled(VrhaMem._re_usage, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group("USAGE")))
            raise ParsingDone

    # write 4 bytes, got -1: Connection timed out
    _re_connention = re.compile(r'(?P<CONNECTION>.+Connection\s+timed\s+out)')

    def _parse_connection_error(self, line):
        if self._regex_helper.search_compiled(VrhaMem._re_connention, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group("CONNECTION")))
            raise ParsingDone

    # address 0x1 is not aligned to a multiple of 4
    _re_address = re.compile(r'(?P<ADDRESS>address.+is\s+not\s+aligned\s+to.*)')

    def _parse_address_error(self, line):
        if self._regex_helper.search_compiled(VrhaMem._re_address, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group("ADDRESS")))
            raise ParsingDone

    def _parse_line(self, line):
        self.current_ret["RESULT"] = line
        raise ParsingDone


